import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative distance of each machine's post-assignment load from the current makespan target M = max(max load, job), normalised by M."""
    M = max(float(np.max(loads)), float(job))
    return -np.abs(loads + job - M) / (M + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative clipped overshoot of post-load above the current mean load, for tiny jobs only."""
    m = loads.shape[0]
    mean_past = past_jobs.mean() if past_jobs.size else job
    if past_jobs.size < 5 or job > 0.25 * mean_past:
        return np.zeros(m)
    L = max(loads.mean(), 1e-9)
    x = loads + job
    return -np.clip((x - L) / L, -1.0, 1.0)
